<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue'; import InputError from '@/Components/InputError.vue'; import PortalLayout from '@/Layouts/PortalLayout.vue'; import { Head,Link,router,useForm } from '@inertiajs/vue3'; const props=defineProps({lead:{type:Object,required:true},statuses:{type:Array,required:true},products:{type:Array,required:true},salesOfficers:{type:Array,required:true}}); const leadForm=useForm({status:props.lead.status,assigned_to:props.lead.assigned_to||'',follow_up_date:props.lead.follow_up_date||'',product_id:props.lead.product_id||''}); const noteForm=useForm({body:'',is_private:true}); const saveLead=()=>leadForm.put(route('admin.leads.update',props.lead.id),{preserveScroll:true}); const addNote=()=>noteForm.post(route('admin.leads.notes.store',props.lead.id),{preserveScroll:true,onSuccess:()=>noteForm.reset('body')}); const saveDemo=(demo)=>router.put(route('admin.demo-requests.update',demo.uuid),{status:demo.status,scheduled_at:demo.scheduled_at,assigned_to:demo.assigned_to},{preserveScroll:true}); const convert=()=>{if(window.confirm('Convert this lead to a customer?'))router.post(route('admin.leads.convert',props.lead.id));};
</script>
<template><Head :title="lead.organization||lead.name"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="leads"/></template><div v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</div><div class="mb-6 flex flex-col gap-4 sm:flex-row sm:justify-between"><div><Link :href="route('admin.leads.index')" class="text-sm font-bold text-cyan-700">← CRM pipeline</Link><h1 class="mt-2 text-3xl font-bold">{{ lead.organization||lead.name }}</h1><p class="mt-2 text-slate-500">{{ lead.lead_number }} · {{ lead.name }} · {{ lead.email }}</p></div><div><Link v-if="lead.converted_customer" :href="route('admin.customers.show',lead.converted_customer.uuid)" class="form-button">View {{ lead.converted_customer.customer_number }}</Link><button v-else class="form-button" @click="convert">Convert to customer</button></div></div><div class="grid gap-6 xl:grid-cols-[1fr_340px]"><div class="space-y-6"><section class="rounded-2xl bg-white p-6 shadow-sm"><h2 class="text-xl font-bold">Opportunity</h2><dl class="mt-5 grid gap-5 sm:grid-cols-2"><div><dt class="text-xs font-bold uppercase text-slate-400">Contact</dt><dd class="mt-1">{{ lead.name }}<br/>{{ lead.phone||'No phone' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Location</dt><dd class="mt-1">{{ lead.location||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Organization type</dt><dd class="mt-1 capitalize">{{ lead.organization_type||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Expected users</dt><dd class="mt-1">{{ lead.number_of_users||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Source</dt><dd class="mt-1">{{ lead.source||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Created</dt><dd class="mt-1">{{ new Date(lead.created_at).toLocaleString() }}</dd></div></dl></section>
<section class="rounded-2xl bg-white p-6 shadow-sm"><h2 class="text-xl font-bold">Demo requests</h2><div class="mt-5 space-y-4"><form v-for="demo in lead.demo_requests" :key="demo.uuid" class="rounded-xl border border-slate-200 p-4" @submit.prevent="saveDemo(demo)"><div class="flex flex-col gap-4 lg:flex-row lg:items-end"><label class="flex-1">Status<select v-model="demo.status"><option value="pending">Pending</option><option value="scheduled">Scheduled</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label><label class="flex-1">Scheduled date and time<input v-model="demo.scheduled_at" type="datetime-local"/></label><label class="flex-1">Sales officer<select v-model="demo.assigned_to"><option value="">Unassigned</option><option v-for="user in salesOfficers" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><button class="form-button !py-2">Save demo</button></div><p class="mt-3 text-sm text-slate-500">Requested: {{ demo.preferred_demo_date||'Any date' }} {{ demo.preferred_demo_time||'' }} · {{ demo.product?.name||'No product' }}</p><p v-if="demo.message" class="mt-2 text-sm text-slate-600">{{ demo.message }}</p></form><p v-if="!lead.demo_requests.length" class="text-slate-500">No demo requests linked.</p></div></section>
<section class="rounded-2xl bg-white p-6 shadow-sm"><h2 class="text-xl font-bold">Notes</h2><form class="mt-4" @submit.prevent="addNote"><textarea v-model="noteForm.body" required rows="3" class="w-full" placeholder="Add sales context or next-step notes."/><InputError :message="noteForm.errors.body"/><div class="mt-3 flex justify-between"><label class="flex items-center gap-2 text-sm"><input v-model="noteForm.is_private" type="checkbox" class="!mt-0"/>Internal</label><button class="form-button !px-4 !py-2">Add note</button></div></form><div class="mt-5 space-y-3"><article v-for="note in lead.notes" :key="note.uuid" class="rounded-xl bg-slate-50 p-4"><p class="whitespace-pre-line">{{ note.body }}</p><p class="mt-2 text-xs text-slate-500">{{ note.author?.name||'System' }} · {{ new Date(note.created_at).toLocaleString() }}</p></article></div></section>
<section class="rounded-2xl bg-white p-6 shadow-sm"><h2 class="text-xl font-bold">Activity history</h2><ol class="mt-5 space-y-4"><li v-for="activity in lead.activities" :key="activity.uuid" class="border-l-2 border-cyan-200 pl-4"><p class="font-bold">{{ activity.description }}</p><p class="text-xs text-slate-500">{{ activity.actor?.name||'System' }} · {{ new Date(activity.created_at).toLocaleString() }}</p></li></ol></section></div>
<aside><form class="sticky top-5 rounded-2xl bg-white p-6 shadow-sm" @submit.prevent="saveLead"><h2 class="text-xl font-bold">Pipeline controls</h2><div class="mt-5 space-y-4"><label>Status<select v-model="leadForm.status"><option v-for="status in statuses" :key="status" :value="status">{{ status.replaceAll('_',' ') }}</option></select><InputError :message="leadForm.errors.status"/></label><label>Product<select v-model="leadForm.product_id"><option value="">Not selected</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.name }}</option></select></label><label>Assigned sales officer<select v-model="leadForm.assigned_to"><option value="">Unassigned</option><option v-for="user in salesOfficers" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label>Follow-up date<input v-model="leadForm.follow_up_date" type="date"/></label><button class="form-button w-full" :disabled="leadForm.processing">Save changes</button></div></form></aside></div></PortalLayout></template>
